const GIFTS_SOURCE_SLUG = "gifts-and-promotions";
const GIFTS_CATS = {
  kitchen: { id: "10", slug: "kitchen-and-bar", name: "Kitchen & Bar" },
  travel: { id: "11", slug: "travel-accessories", name: "Travel Accessories" },
  personal: { id: "12", slug: "personal-accessories", name: "Personal Accessories" },
  giftSets: { id: "13", slug: "gift-sets", name: "Gift Sets" },
} as const;
// Route the supplier's single "Gifts & Promotions" into storefront
// categories by subcategory (user request). Unmapped subs fall to Personal.
const GIFTS_SPLIT: Record<string, { id: string; slug: string; name: string }> = {
  "cutting-boards-cake-pans-kitchen": GIFTS_CATS.kitchen,
  "bbq-sets-and-utensils": GIFTS_CATS.kitchen,
  "flasks-flask-sets-and-accessories": GIFTS_CATS.kitchen,
  "scented-candles": GIFTS_CATS.kitchen,
  "cigar-accessories-and-bar-gift-sets": GIFTS_CATS.kitchen,
  "bar-gift-sets": GIFTS_CATS.giftSets,
  "travel-items": GIFTS_CATS.travel,
  "passport-holders": GIFTS_CATS.travel,
  "travel-jewelry-boxes": GIFTS_CATS.travel,
  "luggage-tags": GIFTS_CATS.travel,
  "large-jewelry-boxes": GIFTS_CATS.travel,
  "crossbody-bags": GIFTS_CATS.travel,
  "personal-items": GIFTS_CATS.personal,
  "wallets": GIFTS_CATS.personal,
  "wallets-with-strap": GIFTS_CATS.personal,
  "wallets-bifold-flip-id": GIFTS_CATS.personal,
  "wallets-bifold": GIFTS_CATS.personal,
  "checkbook-covers": GIFTS_CATS.personal,
  "money-clips": GIFTS_CATS.personal,
  "promotional-items": GIFTS_CATS.personal,
  "bison-river-knives": GIFTS_CATS.personal,
  // FOMA's own products from the dissolved "Best Sellers" category.
  "pocket-knives": GIFTS_CATS.personal,
  "lighters": GIFTS_CATS.personal,
};
function giftsCategoryFor(subSlug: string) {
  return GIFTS_SPLIT[subSlug] ?? GIFTS_CATS.personal;
}

/* ------------------------------------------------------------------ */
/* PROMOTED_CATEGORIES — storefront categories that exist only here,   */
/* built out of subcategories lifted from wherever the feed filed them.*/
/*                                                                     */
/* Currently EMPTY. "Leatherette Tumblers" was the only tenant (1 Aug); */
/* on 3 Aug the user moved that line back under Drinkware as a single   */
/* subcategory, so nothing is promoted any more. The hook stays because  */
/* it is the one place a family can be lifted out of the feed's         */
/* category — add an entry here plus its CATEGORY_BY_SUBSLUG rows and    */
/* an ADDED_SUBCATEGORIES key to bring a top-level tile back.           */
/* ------------------------------------------------------------------ */
const PROMOTED_CATS: Record<string, { id: string; slug: string; name: string }> = {
  // Patches (16 Aug 2026). The 240 leatherette patches are an ADDED_PRODUCTS
  // line — the supplier feed has no patch category at all — so nothing routes
  // here from the feed and the tile only exists because this entry, keyed to
  // ADDED_SUBCATEGORIES["patches"], makes normalizeCatalog create it.
  patches: { id: "14", slug: "patches", name: "Patches" },
};

/* Subcategory slug -> the category that owns it, overriding whatever the
   feed (or the polar-camel merge) would otherwise assign. */
const CATEGORY_BY_SUBSLUG: Record<string, { id: string; slug: string; name: string }> = {};

/* ------------------------------------------------------------------ */
/* SUBCATEGORY_RENAMES — typos in the supplier's own subcategory names. */
/* Keyed by the post-stripBrand name, and applied to BOTH the category  */
/* tile and every product's eyebrow, so the two can never disagree.     */
/* Overriding the slug as well changes the URL, so each entry needs a   */
/* redirect from the old slug in next.config.ts.                        */
/* ------------------------------------------------------------------ */
const SUBCATEGORY_RENAMES: Record<string, { slug: string; name: string }> = {
  // Feed ships "Tumbers" — the only misspelling in the taxonomy.
  "30 oz. Tumbers": { slug: "30-oz-tumblers", name: "30 oz. Tumblers" },
};
const renameSubName = (name: string) => SUBCATEGORY_RENAMES[name]?.name ?? name;

function normalizeCatalog(): { products: RawProduct[]; categories: RawCategory[] } {
  const subSlugBySubId = new Map<string, string>();
  const categories: RawCategory[] = [];
  let target: RawCategory | undefined;

  const addSub = (cat: RawCategory, sc: RawCategory["subcategories"][number]) => {
    const cleaned = stripBrand(sc.name);
    const renamed = SUBCATEGORY_RENAMES[cleaned];
    let slug = renamed?.slug ?? stripBrandSlug(sc.slug);
    const taken = new Set(cat.subcategories.map((s) => s.slug));
    if (taken.has(slug)) {
      let i = 2;
      while (taken.has(`${slug}-${i}`)) i++;
      slug = `${slug}-${i}`;
    }
    subSlugBySubId.set(sc.subId, slug);
    cat.subcategories.push({ ...sc, slug, name: renamed?.name ?? cleaned });
  };

  for (const c of data.categories) {
    if (c.slug === MERGE_SOURCE_SLUG || c.slug === MERGE_TARGET.slug) {
      if (!target) {
        target = { ...MERGE_TARGET, subcategories: [] };
        categories.push(target);
      }
      for (const sc of c.subcategories) addSub(target, sc);
      continue;
    }
    if (c.slug === GIFTS_SOURCE_SLUG) {
      for (const sc of c.subcategories) {
        const t = giftsCategoryFor(stripBrandSlug(sc.slug));
        let gcat = categories.find((x) => x.slug === t.slug);
        if (!gcat) {
          gcat = { id: t.id, slug: t.slug, name: t.name, subcategories: [] };
          categories.push(gcat);
        }
        addSub(gcat, sc);
      }
      continue;
    }
    const cat: RawCategory = { ...c, subcategories: [] };
    categories.push(cat);
    for (const sc of c.subcategories) addSub(cat, sc);
  }

  // Create any brand-new top-level categories an ADDED_SUBCATEGORIES key
  // introduces (e.g. "gift-sets") that no native feed subcategory ever
  // routes to via GIFTS_SPLIT/MERGE_TARGET — without this, the category
  // object never exists by the time the loop below runs and the whole
  // tile silently vanishes (same class of bug as the polar-camel merge).
  for (const t of [...Object.values(GIFTS_CATS), ...Object.values(PROMOTED_CATS)]) {
    if (ADDED_SUBCATEGORIES[t.slug] && !categories.some((c) => c.slug === t.slug)) {
      categories.push({ id: t.id, slug: t.slug, name: t.name, subcategories: [] });
    }
  }

  // Append any FomaPrint-introduced subcategories to their category.
  for (const cat of categories) {
    for (const sc of ADDED_SUBCATEGORIES[cat.slug] ?? []) addSub(cat, sc);
  }

  // Trim the feed to the FomaPrint assortment, then inject curated additions
  // the scrape doesn't carry (skipping any a later scrape may already include).
  const kept = data.products.filter(
    (p) => !REMOVED_SKUS.has(p.sku.toUpperCase()),
  );
  const present = new Set(kept.map((p) => p.sku.toUpperCase()));
  const sourceProducts = [
    ...kept,
    ...ADDED_PRODUCTS.filter((p) => !present.has(p.sku.toUpperCase())),
  ];

  const products = sourceProducts.map((p) => {
    const merged = p.categorySlug === MERGE_SOURCE_SLUG;
    const override = SUB_OVERRIDES[p.sku.toUpperCase()];
    const effectiveSubId = override?.subId ?? p.subId;
    const fallbackSlug = subSlugBySubId.get(effectiveSubId) ?? p.subSlug;
    const subSlug = override
      ? subSlugBySubId.get(override.subId) ?? override.subSlug
      : fallbackSlug;
    let categoryId = merged ? MERGE_TARGET.id : p.categoryId;
    let categorySlug = merged ? MERGE_TARGET.slug : p.categorySlug;
    let categoryName = merged ? MERGE_TARGET.name : p.categoryName;
    if (p.categorySlug === GIFTS_SOURCE_SLUG) {
      const t = giftsCategoryFor(subSlug);
      categoryId = t.id;
      categorySlug = t.slug;
      categoryName = t.name;
    }
    // Promotion wins over both the feed and the polar-camel merge above.
    const promoted = CATEGORY_BY_SUBSLUG[subSlug];
    if (promoted) {
      categoryId = promoted.id;
      categorySlug = promoted.slug;
      categoryName = promoted.name;
    }
    return {
      ...p,
      name: NAME_OVERRIDES[p.sku.toUpperCase()] ?? stripBrand(p.name),
      categoryId,
      categorySlug,
      categoryName,
      subId: effectiveSubId,
      subSlug,
      subName: renameSubName(stripBrand(override?.subName ?? p.subName)),
    };
  });

  return { products, categories };
}

const { products: normProducts, categories: normCategories } = normalizeCatalog();

